// [MEDIUM_PRIORITY] VALIDATION: Double conversion safe
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.intent.classifierimport timber.log.Timberimport kotlin.math.lnimport kotlin.math.sqrtimport javax.inject.Singleton/** * NOUS — TF-IDF Embedder (temporary semantic embedder until Module 6). * * **Problem this solves**: The original FakeEmbedder used hash-based vectors, * which meant cosine similarity had NO semantic meaning. "Torch on" and * "flashlight on" would get completely different vectors despite meaning * the same thing. * * **Solution**: TF-IDF (Term Frequency - Inverse Document Frequency) creates * vectors where semantically similar texts get similar vectors. Words like * "torch" and "flashlight" that appear in the same canonical phrases will * contribute to similar vector dimensions. * * ## How it works * *   1. Build a vocabulary from all canonical phrases (corpus) *   2. Compute IDF for each word: `idf(word) = ln(N / df(word))` *      where N = total documents, df = documents containing word *   3. For input text: compute TF-IDF vector *      - TF(word) = count in text / total words in text *      - TF-IDF(word) = TF(word) × IDF(word) *   4. Vector dimension = vocabulary size (typically 200-500 words) * * ## Limitations * *   - No synonym detection ("torch" ≠ "flashlight" unless they co-occur) *   - No word order sensitivity *   - No semantic understanding beyond bag-of-words * * Module 6 will replace this with TFLite MiniLM-L6 (384-dim, real semantic * embeddings via transformer architecture). * * @see <a href="docs/spec/module2-spec-review.pdf">§4.1 Stage 3</a> *//** * TfIdf-based embedder — hash-based fallback when no real ML model is loaded. * * Strategy §14.2 Table 10: Real impl is OmniSlmEmbedder (Module 6 Vision). * Until then, this stub provides keyword-overlap embeddings (384-dim * hashed TF-IDF vector) — sufficient for IntentClassifier's Stage 3. * * Constructed via [com.roshan.persona.brain.di.BrainModule.provideEmbedder] * (not @Inject) because it takes a `corpus` parameter. */@Singletonclass TfIdfEmbedder(    corpus: List<String> = defaultCorpus(),) : EmbedderInterface {    /** Vocabulary: word → index in vector. */    private val vocabulary: Map<String, Int>    /** IDF weight per word. */    private val idfWeights: Map<String, Float>    /** Vector dimension (vocabulary size). */    val dimension: Int    init {        // Build vocabulary from corpus        val vocabBuilder = mutableMapOf<String, Int>()        val documentFrequency = mutableMapOf<String, Int>()        for (doc in corpus) {            val words = tokenize(doc).toSet()  // unique words per doc for DF            for (word in words) {                documentFrequency[word] = (documentFrequency[word] ?: 0) + 1            }        }        // Assign indices        var index = 0        for (word in documentFrequency.keys.sorted()) {            vocabBuilder[word] = index            index++        }        vocabulary = vocabBuilder        dimension = vocabulary.size        // Compute IDF: ln(N / df) with smoothing        val n = corpus.size.toFloat()        idfWeights = documentFrequency.mapValues { (_, df) ->            ln((n + 1f) / (df + 1f)) + 1f  // smoothed IDF        }        Timber.tag("NOUS.L0").v("TfIdfEmbedder initialized: vocab=%d words", dimension)    }    /**     * Embed [text] into a TF-IDF vector.     *     * @return kotlin.Result containing FloatArray of size [dimension]     */    override suspend fun embed(text: String): kotlin.Result<FloatArray> {        val words = tokenize(text)        if (words.isEmpty()) {            return kotlin.Result.success(FloatArray(dimension))        }        // Compute term frequency        val termFreq = mutableMapOf<String, Int>()        for (word in words) {            termFreq[word] = (termFreq[word] ?: 0) + 1        }        val totalWords = words.size.toFloat()        // Build TF-IDF vector        val vector = FloatArray(dimension)        for ((word, count) in termFreq) {            val index = vocabulary[word] ?: continue  // skip OOV words            val tf = count / totalWords            val idf = idfWeights[word] ?: 1f            vector[index] = tf * idf        }        // L2 normalize (so cosine similarity works correctly)        val norm = sqrt(vector.sumOf { (it * it).toDouble() }).toFloat()        if (norm > 0f) {            for (i in vector.indices) {                vector[i] /= norm            }        }        return kotlin.Result.success(vector)    }    /**     * Tokenize text into lowercase words.     *     * Strips punctuation, splits on whitespace, lowercases.     * Includes simple stemming (strip common suffixes: -ing, -ed, -s).     */    private fun tokenize(text: String): List<String> {        return text            .lowercase()            .replace(Regex("[^a-z0-9\\s]"), " ")            .split(Regex("\\s+"))            .filter { it.isNotBlank() && it.length > 1 }            .map { stem(it) }    }    /**     * Simple Porter-lite stemmer.     *     * Strips common suffixes to normalize words:     *   - "calling" → "call"     *   - "called" → "call"     *   - "calls" → "call"     */    private fun stem(word: String): String {        // Order matters: check longer suffixes first        for (suffix in SUFFIXES) {            if (word.length > suffix.length + 2 && word.endsWith(suffix)) {                return word.dropLast(suffix.length)            }        }        return word    }    companion object {        /** Suffixes to strip (Porter-lite). Order: longest first. */        private val SUFFIXES = listOf(            "ing", "ied", "ies", "ied", "ied",            "ed", "es", "er", "ly", "s",        )        /**         * Default corpus — all canonical phrases from [EmbeddingIntentMatcher].         *         * This ensures the vocabulary covers all intent-related words.         */        fun defaultCorpus(): List<String> {            return EmbeddingIntentMatcher.CANONICAL_PHRASES.values.flatten()        }    }}